document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("papier-mache-gallery");e&&[{title:"Kalamdan (Pen Case)",description:"A traditional pen case ornately decorated with the Hazara motif, showcasing delicate gold detailing.",motif:"Gul-e-Hazara",imgSrc:"assets/papier-mache-1.jpg"},{title:"Decorative Vase",description:"A large vase painted with Chinar leaves and singing birds, highlighting the natural beauty of Kashmir.",motif:"Chinar and Birds",imgSrc:"assets/papier-mache-2.jpg"},{title:"Jewelry Box",description:"A small, exquisitely detailed jewelry box featuring Persian arabesque patterns in rich blue and gold.",motif:"Persian Arabesque",imgSrc:"assets/papier-mache-3.jpg"},{title:"Wall Plate",description:"A decorative wall plate illustrating a Darbar (royal court) scene surrounded by a border of intricate florals.",motif:"Darbar & Florals",imgSrc:"assets/papier-mache-4.jpg"}].forEach((a,t)=>{const i=document.createElement("div");i.className="gallery-card",i.tabIndex=0,i.setAttribute("aria-label",`Gallery item: ${a.title}`),i.innerHTML=`\n                <img src="${a.imgSrc}" alt="${a.title}" loading="lazy" onerror="this.style.display='none'; this.nextElementSibling.style.display='flex';">\n                <div class="animated-placeholder" style="display:none; height: 200px;">Image of ${a.title}</div>\n                <div class="gallery-card-content">\n                    <h3>${a.title}</h3>\n                    <p style="color: var(--primary-gold); font-size: 0.8rem; text-transform: uppercase; margin-bottom: 8px;">Motif: ${a.motif}</p>\n                    <p>${a.description}</p>\n                </div>\n            `,e.appendChild(i)});const a=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&e.target.classList.add("visible")})},{threshold:.1,rootMargin:"0px 0px -50px 0px"});document.querySelectorAll(".fade-in-section").forEach(e=>{a.observe(e)})});